// Intended function: roll weighted bases and tier-scaled compatible affixes from a reproducible event seed so save/replay results remain stable.
#include "gameplay/LootSystem.hpp"
#include "core/Determinism.hpp"
#include <algorithm>
namespace elysium{namespace{float u(std::uint64_t x){return float((mix64(x)>>40U)&0xFFFFFFU)/float(0xFFFFFFU);}LootTier tier(float r,float mf){float b=std::clamp(mf,0.f,3.f)*.04f;if(r<.002f+b*.08f)return LootTier::Artifact;if(r<.015f+b*.16f)return LootTier::Relic;if(r<.07f+b*.35f)return LootTier::Epic;if(r<.23f+b*.5f)return LootTier::Rare;if(r<.55f+b*.7f)return LootTier::Uncommon;return LootTier::Common;}}
GeneratedLoot rollLoot(const LootTable&t,const LootRollContext&c){GeneratedLoot o;if(t.bases.empty())return o;auto seed=mix64(c.worldSeed^mix64(c.sourceStableId)^mix64(c.eventOrdinal)^t.tableId);std::uint64_t total=0;for(auto&b:t.bases)total+=std::max(1u,b.weight);auto pick=mix64(seed^1)%total;const LootBaseDefinition*base=&t.bases.front();for(auto&b:t.bases){auto w=std::max(1u,b.weight);if(pick<w){base=&b;break;}pick-=w;}o.baseItemId=base->itemId;o.tier=tier(u(seed^2),c.magicFind);o.stableItemId=mix64(seed^mix64(base->itemId));o.provenanceSeed=seed;const int count=std::min<int>(int(o.tier),4);std::vector<const LootAffixDefinition*>pool;for(auto&a:t.affixes)if(a.tagMask&base->tagMask)pool.push_back(&a);std::sort(pool.begin(),pool.end(),[](auto*a,auto*b){return a->affixId<b->affixId;});for(int i=0;i<count&&!pool.empty();++i){auto idx=std::size_t(mix64(seed^std::uint64_t(10+i))%pool.size());auto*a=pool[idx];float r=u(seed^std::uint64_t(30+i));o.affixes.push_back({a->affixId,a->minValue+(a->maxValue-a->minValue)*r});pool.erase(pool.begin()+idx);}o.sockets=std::uint8_t(std::min<int>(base->maxSockets,(int(o.tier)>=int(LootTier::Rare)?int(mix64(seed^99)%4):0)));return o;}
}
